namespace {
constexpr char kFirmwareVersion[]="0.4.0", kNvs[]="knxrouter";
constexpr uint16_t kConfigVersion=1, kDefaultPort=3671;
constexpr uint32_t kDefaultMulticast=0xE000170CUL;
constexpr size_t kIpBufferSize=512,kLogEntries=12,kLogRawBytes=64;
struct RouterConfig { uint16_t version=kConfigVersion; bool paSet=false; uint16_t pa=0; uint32_t multicast=kDefaultMulticast; uint16_t port=kDefaultPort; uint32_t timeoutMs=15000, probeMs=3000; };
enum class Diag:uint8_t { Idle,Running,ResetReceived,Absent,ProtocolError,BusMonitor };

ESPBase espBase(ROUTER_NAME,kFirmwareVersion); Preferences prefs; RouterConfig config;
HardwareSerial knxSerial(2); Esp32Platform knxPlatform(&knxSerial); Bau091A knxBau(knxPlatform); KnxFacade<Esp32Platform,Bau091A> knx(knxBau);
WiFiUDP knxIpUdp;
struct IpLogEntry { uint32_t ms; IPAddress remoteIp; uint16_t remotePort,source,destination; uint8_t hop,rawLen; bool group,truncated; ApduType apci; uint8_t raw[kLogRawBytes]; };
IpLogEntry ipLog[kLogEntries]{}; size_t ipLogHead=0,ipLogCount=0;
bool ipListenEnabled=true,ipJoined=false,ipDisplayPaused=false; uint16_t ipLastIgnoredService=0; uint32_t ipJoinedAt=0,ipJoinAttempts=0,ipDatagrams=0,ipTelegrams=0,ipIgnored=0,ipErrors=0,ipLogLosses=0,ipLastGotIps=0;
Diag diag=Diag::Idle; uint32_t diagStart=0,lastProbe=0,attempts=0,resetInd=0,stateInd=0,tpFrames=0,overflows=0,lastByteUs=0; uint8_t frame[64]{}; size_t frameLen=0; bool configLoaded=false; char lastDiagnostic[96]="Diagnostic non lance",lastError[96]="Aucune";
volatile uint32_t wifiAssociatedAt=0,wifiGotIpAt=0,wifiLastDisconnectAt=0,wifiAssociations=0,wifiDisconnects=0,wifiGotIps=0;
volatile uint8_t wifiLastReason=0,wifiLastChannel=0; uint8_t wifiLastBssid[6]{}; int32_t wifiRssiMin=0,wifiRssiLast=0; uint32_t wifiLastSample=0;

bool elapsed(uint32_t now,uint32_t since,uint32_t duration){return uint32_t(now-since)>=duration;}
void setText(char* dst,size_t cap,const char* value){strlcpy(dst,value?value:"",cap);}
const char* diagText(){switch(diag){case Diag::Idle:return "Non lance";case Diag::Running:return "En cours";case Diag::ResetReceived:return "Reponse recue";case Diag::Absent:return "NanoBCU non detecte";case Diag::ProtocolError:return "Erreur de protocole";case Diag::BusMonitor:return "Bus monitor passif";}return "Inconnu";}
const char* wifiReason(uint8_t r){switch(r){case 2:return "AUTH_EXPIRE";case 3:return "AUTH_LEAVE";case 4:return "ASSOC_EXPIRE";case 8:return "ASSOC_LEAVE";case 15:return "4WAY_HANDSHAKE_TIMEOUT";case 36:return "STA_LEAVING";case 39:return "TIMEOUT";case 200:return "BEACON_TIMEOUT";case 201:return "NO_AP_FOUND";case 202:return "AUTH_FAIL";case 203:return "ASSOC_FAIL";case 204:return "HANDSHAKE_TIMEOUT";case 205:return "CONNECTION_FAIL";case 207:return "ROAMING";default:return "AUTRE";}}
void wifiEvent(WiFiEvent_t event,WiFiEventInfo_t info){uint32_t now=millis();if(event==ARDUINO_EVENT_WIFI_STA_CONNECTED){wifiAssociatedAt=now;wifiLastChannel=info.wifi_sta_connected.channel;memcpy(wifiLastBssid,info.wifi_sta_connected.bssid,6);++wifiAssociations;Serial.printf("[WIFI-DIAG] associe t=%lu ms canal=%u BSSID=%02X:%02X:%02X:%02X:%02X:%02X depuis_deconnexion=%lu ms\n",now,unsigned(wifiLastChannel),wifiLastBssid[0],wifiLastBssid[1],wifiLastBssid[2],wifiLastBssid[3],wifiLastBssid[4],wifiLastBssid[5],wifiLastDisconnectAt?now-wifiLastDisconnectAt:now);}else if(event==ARDUINO_EVENT_WIFI_STA_GOT_IP){wifiGotIpAt=now;++wifiGotIps;Serial.printf("[WIFI-DIAG] DHCP t=%lu ms delai_apres_association=%lu ms IP=%s RSSI=%ld dBm\n",now,wifiAssociatedAt?now-wifiAssociatedAt:0,WiFi.localIP().toString().c_str(),long(WiFi.RSSI()));}else if(event==ARDUINO_EVENT_WIFI_STA_DISCONNECTED){wifiLastDisconnectAt=now;wifiLastReason=info.wifi_sta_disconnected.reason;memcpy(wifiLastBssid,info.wifi_sta_disconnected.bssid,6);++wifiDisconnects;Serial.printf("[WIFI-DIAG] deconnexion t=%lu ms motif=%u (%s) BSSID=%02X:%02X:%02X:%02X:%02X:%02X RSSI_avant=%ld dBm\n",now,unsigned(wifiLastReason),wifiReason(wifiLastReason),wifiLastBssid[0],wifiLastBssid[1],wifiLastBssid[2],wifiLastBssid[3],wifiLastBssid[4],wifiLastBssid[5],long(wifiRssiLast));}else if(event==ARDUINO_EVENT_WIFI_STA_LOST_IP)Serial.printf("[WIFI-DIAG] perte IP t=%lu ms\n",now);}
void formatPa(uint16_t a,char* out,size_t cap){snprintf(out,cap,"%u.%u.%u",(a>>12)&15,(a>>8)&15,a&255);}
bool parsePa(const char* s,bool& configured,uint16_t& out){configured=false;out=0;if(!s||!*s)return true;unsigned a,l,d;char x;if(sscanf(s,"%u.%u.%u%c",&a,&l,&d,&x)!=3||a>15||l>15||d>255)return false;configured=true;out=(a<<12)|(l<<8)|d;return true;}
void formatIp(uint32_t a,char* out,size_t cap){snprintf(out,cap,"%u.%u.%u.%u",(a>>24)&255,(a>>16)&255,(a>>8)&255,a&255);}
bool parseIp(const char* s,uint32_t& out){unsigned a,b,c,d;char x;if(!s||sscanf(s,"%u.%u.%u.%u%c",&a,&b,&c,&d,&x)!=4||a<224||a>239||b>255||c>255||d>255)return false;out=(a<<24)|(b<<16)|(c<<8)|d;return true;}
bool parseUInt(const char* s,uint32_t lo,uint32_t hi,uint32_t& out){if(!s||!*s)return false;char* e=nullptr;unsigned long v=strtoul(s,&e,10);if(!e||*e||v<lo||v>hi)return false;out=v;return true;}
bool valid(const RouterConfig& c){uint8_t first=c.multicast>>24;return c.version==kConfigVersion&&first>=224&&first<=239&&c.port&&c.timeoutMs>=3000&&c.timeoutMs<=60000&&c.probeMs>=500&&c.probeMs<=10000&&c.probeMs<c.timeoutMs;}
bool loadConfig(){if(!prefs.begin(kNvs,true))return false;RouterConfig candidate;size_t n=prefs.getBytesLength("config")==sizeof(candidate)?prefs.getBytes("config",&candidate,sizeof(candidate)):0;prefs.end();if(n!=sizeof(candidate)||!valid(candidate))return false;config=candidate;return true;}
bool saveConfig(const RouterConfig& c){if(!valid(c)||!prefs.begin(kNvs,false))return false;size_t n=prefs.putBytes("config",&c,sizeof(c));prefs.end();return n==sizeof(c);}

IPAddress multicastAddress(){return IPAddress(config.multicast>>24,(config.multicast>>16)&255,(config.multicast>>8)&255,config.multicast&255);}
const char* apciName(ApduType t){switch(t){case GroupValueRead:return "GroupValueRead";case GroupValueResponse:return "GroupValueResponse";case GroupValueWrite:return "GroupValueWrite";case IndividualAddressWrite:return "IndividualAddressWrite";case IndividualAddressRead:return "IndividualAddressRead";case IndividualAddressResponse:return "IndividualAddressResponse";case PropertyValueRead:return "PropertyValueRead";case PropertyValueResponse:return "PropertyValueResponse";case PropertyValueWrite:return "PropertyValueWrite";default:return "Autre APCI";}}
void formatGroup(uint16_t a,char* out,size_t cap){snprintf(out,cap,"%u/%u/%u",(a>>11)&31,(a>>8)&7,a&255);}
void leaveMulticast(){if(ipJoined){knxIpUdp.stop();ipJoined=false;Serial.println(F("[KNX-IP RX] Ecoute multicast arretee"));}}
void joinMulticast(){if(!ipListenEnabled||WiFi.status()!=WL_CONNECTED)return;leaveMulticast();++ipJoinAttempts;ipJoined=knxIpUdp.beginMulticast(multicastAddress(),config.port)==1;if(ipJoined){ipJoinedAt=millis();ipLastGotIps=wifiGotIps;Serial.printf("[KNX-IP RX] Ecoute seule active sur %s:%u, STA=%s\n",multicastAddress().toString().c_str(),config.port,WiFi.localIP().toString().c_str());}else{++ipErrors;Serial.println(F("[KNX-IP RX] Echec inscription multicast"));}}
void addIpLog(IPAddress remote,uint16_t port,CemiFrame& cemi,const uint8_t* raw,size_t rawLen){if(ipDisplayPaused){++ipLogLosses;return;}if(ipLogCount==kLogEntries)++ipLogLosses;else ++ipLogCount;IpLogEntry& e=ipLog[ipLogHead];e.ms=millis();e.remoteIp=remote;e.remotePort=port;e.source=cemi.sourceAddress();e.destination=cemi.destinationAddress();e.group=cemi.addressType()==GroupAddress;e.hop=cemi.hopCount();e.apci=cemi.apdu().type();e.rawLen=min(rawLen,kLogRawBytes);e.truncated=rawLen>kLogRawBytes;memcpy(e.raw,raw,e.rawLen);ipLogHead=(ipLogHead+1)%kLogEntries;}
void processIpDatagram(uint8_t* data,size_t len,IPAddress remote,uint16_t port){
 ++ipDatagrams;
 if(len<6||data[0]!=6||data[1]!=0x10){++ipErrors;return;}
 const uint16_t service=(uint16_t(data[2])<<8)|data[3],declared=(uint16_t(data[4])<<8)|data[5];
 if(declared!=len){++ipErrors;return;}if(service!=RoutingIndication){ipLastIgnoredService=service;++ipIgnored;return;}
 const size_t cemiLen=len-6;if(cemiLen<10){++ipErrors;return;}uint8_t* cemiData=data+6;const size_t add=cemiData[1];
 if(add+10>cemiLen){++ipErrors;return;}const size_t expected=add+size_t(cemiData[add+8])+10;if(expected!=cemiLen){++ipErrors;return;}
 KnxIpRoutingIndication indication(data,len);CemiFrame& cemi=indication.frame();if(!cemi.valid()||cemi.messageCode()!=L_data_ind){++ipErrors;return;}
 ++ipTelegrams;addIpLog(remote,port,cemi,cemiData,cemiLen);
 char src[16],dst[16];formatPa(cemi.sourceAddress(),src,sizeof(src));if(cemi.addressType()==GroupAddress)formatGroup(cemi.destinationAddress(),dst,sizeof(dst));else formatPa(cemi.destinationAddress(),dst,sizeof(dst));
 Serial.printf("[KNX-IP RX #%lu] %s:%u %s -> %s (%s) %s hop=%u; candidat TP - non transmis, mode ecoute\n",ipTelegrams,remote.toString().c_str(),port,src,dst,cemi.addressType()==GroupAddress?"groupe":"individuelle",apciName(cemi.apdu().type()),cemi.hopCount());
}
void serviceIpListener(){
 if(!ipListenEnabled||WiFi.status()!=WL_CONNECTED){leaveMulticast();return;}if(!ipJoined||ipLastGotIps!=wifiGotIps)joinMulticast();if(!ipJoined)return;
 for(uint8_t handled=0;handled<4;++handled){int packet=knxIpUdp.parsePacket();if(packet<=0)break;IPAddress remote=knxIpUdp.remoteIP();uint16_t port=knxIpUdp.remotePort();if(size_t(packet)>kIpBufferSize){uint8_t discard[32];while(knxIpUdp.available())knxIpUdp.read(discard,min(size_t(knxIpUdp.available()),sizeof(discard)));++ipDatagrams;++ipErrors;continue;}uint8_t data[kIpBufferSize];int got=knxIpUdp.read(data,packet);if(got!=packet){++ipDatagrams;++ipErrors;continue;}processIpDatagram(data,got,remote,port);}
}

void startDiagnostic(){while(knxSerial.available())knxSerial.read();diag=Diag::Running;diagStart=millis();lastProbe=diagStart-config.probeMs;attempts=0;frameLen=0;setText(lastDiagnostic,sizeof(lastDiagnostic),"Diagnostic NCN5130 en cours");setText(lastError,sizeof(lastError),"Aucune");Serial.println(F("[NANOBCU] Diagnostic local demarre"));}
void finishFrame(){if(diag!=Diag::BusMonitor||!frameLen)return;++tpFrames;Serial.printf("[TP-RX #%lu] %u octets:",tpFrames,unsigned(frameLen));for(size_t i=0;i<frameLen;++i)Serial.printf(" %02X",frame[i]);Serial.println();frameLen=0;}
void serviceDiagnostic(){
 if(diag==Diag::BusMonitor&&frameLen&&elapsed(micros(),lastByteUs,NANOBCU_FRAME_GAP_US))finishFrame();
 while(knxSerial.available()){uint8_t v=knxSerial.read();if(diag==Diag::Running&&v==0x03){++resetInd;diag=Diag::ResetReceived;setText(lastDiagnostic,sizeof(lastDiagnostic),"U_Reset.ind recu; lecture etat NCN5130");knxSerial.write(0x02);knxSerial.flush();}
 else if(diag==Diag::ResetReceived&&(v&7)==7){++stateInd;diag=Diag::BusMonitor;setText(lastDiagnostic,sizeof(lastDiagnostic),"NCN5130 detecte; bus monitor passif actif");knxSerial.write(0x05);knxSerial.flush();Serial.printf("[NANOBCU] U_State.ind=0x%02X; bus monitor passif\n",v);}
 else if(diag==Diag::BusMonitor){lastByteUs=micros();if(frameLen<sizeof(frame))frame[frameLen++]=v;else{++overflows;frameLen=0;setText(lastError,sizeof(lastError),"Trame UART depasse 64 octets");}}
 else if(diag==Diag::ResetReceived){diag=Diag::ProtocolError;snprintf(lastError,sizeof(lastError),"Reponse etat inattendue 0x%02X",v);}}
 uint32_t now=millis();if(diag==Diag::Running&&elapsed(now,diagStart,config.timeoutMs)){diag=Diag::Absent;setText(lastDiagnostic,sizeof(lastDiagnostic),"NanoBCU non detecte");Serial.println(F("[NANOBCU] NanoBCU non detecte (normal si debranche)"));}
 else if(diag==Diag::Running&&elapsed(now,lastProbe,config.probeMs)){lastProbe=now;++attempts;knxSerial.write(0x01);knxSerial.flush();}
}

void metric(WebResponse& r,const char* label,const char* value){r.write("<div><span class='muted'>");r.write(label);r.write("</span><strong>");r.write(value);r.write("</strong></div>");}
void statePage(WebResponse& r,void*){
 char v[256];
 const uint32_t freeHeap=ESP.getFreeHeap(),minHeap=ESP.getMinFreeHeap();
 const uint32_t largestBlock=ESP.getMaxAllocHeap();
 const uint32_t internalFree=heap_caps_get_free_size(MALLOC_CAP_INTERNAL);
 const uint32_t internalLargest=heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL);
 const bool hasPsram=psramFound();
 const UBaseType_t loopStack=uxTaskGetStackHighWaterMark(nullptr);
 const UBaseType_t idle0Stack=uxTaskGetStackHighWaterMark(xTaskGetIdleTaskHandleForCPU(0));
 const UBaseType_t idle1Stack=uxTaskGetStackHighWaterMark(xTaskGetIdleTaskHandleForCPU(1));
 r.beginPage("KNX - Etat");r.write("<div class='grid'><section class='card'><h2>Routeur KNX</h2><div class='metrics'>");metric(r,"Firmware",espBase.firmwareVersion());metric(r,"Device ID",espBase.deviceId());metric(r,"Hostname",espBase.hostname());snprintf(v,sizeof(v),"%lu s",millis()/1000UL);metric(r,"Uptime",v);r.write("</div></section><section class='card'><h2>Reseau</h2><div class='metrics'>");metric(r,"Wi-Fi",WiFi.status()==WL_CONNECTED?"Connecte":"Deconnecte");metric(r,"Adresse IP",WiFi.localIP().toString().c_str());snprintf(v,sizeof(v),"%ld dBm",long(WiFi.status()==WL_CONNECTED?WiFi.RSSI():wifiRssiLast));metric(r,"RSSI actuel / dernier",v);snprintf(v,sizeof(v),"%ld dBm",long(wifiRssiMin));metric(r,"RSSI minimum connecte",v);snprintf(v,sizeof(v),"%lu / %lu / %lu",wifiAssociations,wifiGotIps,wifiDisconnects);metric(r,"Associations / DHCP / deconnexions",v);snprintf(v,sizeof(v),"%u (%s)",unsigned(wifiLastReason),wifiReason(wifiLastReason));metric(r,"Dernier motif Wi-Fi",v);snprintf(v,sizeof(v),"%02X:%02X:%02X:%02X:%02X:%02X canal %u",wifiLastBssid[0],wifiLastBssid[1],wifiLastBssid[2],wifiLastBssid[3],wifiLastBssid[4],wifiLastBssid[5],unsigned(wifiLastChannel));metric(r,"Dernier point d'acces",v);snprintf(v,sizeof(v),"%lu ms",wifiGotIpAt&&wifiAssociatedAt?wifiGotIpAt-wifiAssociatedAt:0);metric(r,"Dernier delai DHCP",v);metric(r,"Reprise ESP_BASE","Essai 15 s, nouvel essai toutes les 60 s en AP de secours");r.write("</div></section>");
 r.write("<section class='card'><h2>Memoire runtime</h2><div class='metrics'>");snprintf(v,sizeof(v),"%lu octets",freeHeap);metric(r,"Heap libre (instantane)",v);snprintf(v,sizeof(v),"%lu octets",minHeap);metric(r,"Minimum natif depuis demarrage",v);snprintf(v,sizeof(v),"%lu octets",largestBlock);metric(r,"Plus grand bloc allouable",v);snprintf(v,sizeof(v),"%lu octets",internalFree);metric(r,"Memoire interne libre",v);snprintf(v,sizeof(v),"%lu octets",internalLargest);metric(r,"Plus grand bloc interne",v);metric(r,"PSRAM",hasPsram?"Presente":"Absente");if(hasPsram){snprintf(v,sizeof(v),"%lu / %lu octets libres",ESP.getFreePsram(),ESP.getPsramSize());metric(r,"PSRAM libre / totale",v);}snprintf(v,sizeof(v),"%u octets",unsigned(loopStack));metric(r,"Marge pile loop/Web",v);snprintf(v,sizeof(v),"CPU0 %u / CPU1 %u octets",unsigned(idle0Stack),unsigned(idle1Stack));metric(r,"Marge piles idle",v);r.write("</div><p class='muted'>Les marges de pile sont les minima historiques FreeRTOS. Les taches Wi-Fi internes ne sont pas exposees individuellement ici.</p></section>");
 r.write("<section class='card'><h2>NanoBCU NCN5130</h2><div class='metrics'>");metric(r,"Etat",diagText());metric(r,"UART","UART2 RX GPIO16 / TX GPIO17 - 19200 8E1");metric(r,"Mode demande","Diagnostic local puis bus monitor");metric(r,"Mode actif",diag==Diag::BusMonitor?"Bus monitor passif":"Diagnostic local");snprintf(v,sizeof(v),"%lu",attempts);metric(r,"Tentatives",v);snprintf(v,sizeof(v),"%lu",tpFrames);metric(r,"Trames TP recues",v);metric(r,"Dernier diagnostic",lastDiagnostic);metric(r,"Derniere erreur",lastError);r.write("</div><form method='post' action='/knx-diagnostic'><input type='hidden' name='action' value='diagnostic'><button type='submit'>Relancer le diagnostic local</button></form></section>");
 r.write("<section class='card'><h2>Ecoute KNXnet/IP</h2><div class='metrics'>");metric(r,"Etat",!ipListenEnabled?"Desactivee":ipJoined?"Multicast actif":"En attente");snprintf(v,sizeof(v),"%s:%u",multicastAddress().toString().c_str(),config.port);metric(r,"Groupe / port",v);metric(r,"Interface","Wi-Fi STA uniquement");snprintf(v,sizeof(v),"%lu",ipDatagrams);metric(r,"Datagrammes recus",v);snprintf(v,sizeof(v),"%lu",ipTelegrams);metric(r,"Telegrammes valides",v);snprintf(v,sizeof(v),"%lu",ipIgnored);metric(r,"Types ignores",v);snprintf(v,sizeof(v),"0x%04X",ipLastIgnoredService);metric(r,"Dernier service ignore",v);snprintf(v,sizeof(v),"%lu",ipErrors);metric(r,"Erreurs",v);snprintf(v,sizeof(v),"%lu",ipLogLosses);metric(r,"Pertes de journal",v);snprintf(v,sizeof(v),"%lu",ipJoinAttempts);metric(r,"Inscriptions multicast",v);metric(r,"Affichage",ipDisplayPaused?"En pause (reception maintenue)":"Actif");r.write("</div><form method='post' action='/knx-diagnostic'><input type='hidden' name='action' value='");r.write(ipListenEnabled?"listen_stop":"listen_start");r.write("'><button type='submit'>");r.write(ipListenEnabled?"Arreter l'ecoute":"Demarrer l'ecoute");r.write("</button></form><form method='post' action='/knx-diagnostic'><input type='hidden' name='action' value='display_toggle'><button type='submit'>");r.write(ipDisplayPaused?"Reprendre le journal":"Mettre le journal en pause");r.write("</button></form><form method='post' action='/knx-diagnostic'><input type='hidden' name='action' value='clear_log'><button type='submit'>Effacer le journal</button></form><h3>Derniers telegrammes</h3>");
 if(!ipLogCount)r.write("<p class='muted'>Aucun telegramme valide recu.</p>");else for(size_t n=0;n<ipLogCount;++n){size_t idx=(ipLogHead+kLogEntries-1-n)%kLogEntries;IpLogEntry& e=ipLog[idx];char src[16],dst[16];formatPa(e.source,src,sizeof(src));if(e.group)formatGroup(e.destination,dst,sizeof(dst));else formatPa(e.destination,dst,sizeof(dst));snprintf(v,sizeof(v),"<p><strong>+%lu ms - %s:%u</strong><br>%s vers %s (%s), %s, compteur %u<br><code>",e.ms,e.remoteIp.toString().c_str(),e.remotePort,src,dst,e.group?"groupe":"individuelle",apciName(e.apci),e.hop);r.write(v);for(uint8_t j=0;j<e.rawLen;++j){snprintf(v,sizeof(v),"%02X%s",e.raw[j],j+1==e.rawLen?"":" ");r.write(v);}if(e.truncated)r.write(" ...");r.write("</code><br><em>candidat TP - non transmis, mode ecoute</em></p>");}r.write("<p class='muted'>Les donnees restent brutes : aucun DPT n'est deduit sans association connue.</p></section>");
 r.write("<section class='card'><h2>Routage</h2><div class='metrics'>");metric(r,"Verrou compile",ROUTING_ARMED?"ARME":"DESACTIVE");metric(r,"Decodeur KNX","Ecoute seule, sans demarrage de la pile");metric(r,"Routage TP vers IP","Inactif");metric(r,"Routage IP vers TP","Inactif");metric(r,"Tunnels","Inactifs");metric(r,"Emission KNXnet/IP","Aucune emission applicative");r.write("</div></section></div>");r.endPage();
}
void configPage(WebResponse& r,void*){char pa[16]="",mc[20],n[16];if(config.paSet)formatPa(config.pa,pa,sizeof(pa));formatIp(config.multicast,mc,sizeof(mc));r.beginPage("KNX - Configuration");r.write("<section class='card'><p class='muted'>ROUTING_ARMED=0 reste prioritaire. Le groupe et le port servent uniquement a l'ecoute passive; toute emission reste interdite.</p><form method='post' action='/knx-config-save'><label>Adresse physique prevue (vide = non configuree)<input name='physical_address' maxlength='10' placeholder='1.1.0' value='");if(pa[0])r.write(pa);r.write("'></label><label>Multicast KNXnet/IP (ecoute, redemarrage requis)<input name='multicast' maxlength='15' required value='");r.write(mc);snprintf(n,sizeof(n),"%u",config.port);r.write("'></label><label>Port UDP KNXnet/IP (ecoute, redemarrage requis)<input name='port' type='number' min='1' max='65535' required value='");r.write(n);snprintf(n,sizeof(n),"%lu",config.timeoutMs);r.write("'></label><label>Delai diagnostic, ms<input name='diag_timeout' type='number' min='3000' max='60000' required value='");r.write(n);snprintf(n,sizeof(n),"%lu",config.probeMs);r.write("'></label><label>Intervalle sondes, ms<input name='probe_interval' type='number' min='500' max='10000' required value='");r.write(n);r.write("'></label><button type='submit'>Enregistrer explicitement</button></form></section><section class='card'><h2>Parametres fixes</h2><p>UART2 RX GPIO16 / TX GPIO17, 19200 bauds, 8E1.</p><p>Aucun filtrage DPT ou table ETS n'est applique a l'ecoute passive.</p></section>");r.endPage();}
void configPost(WebRequest& q,WebResponse& r,void*){for(const char* name:{"physical_address","multicast","port","diag_timeout","probe_interval"})if(!q.hasArg(name)){r.sendText("Parametres manquants",400);return;}RouterConfig c=config;String pa=q.arg("physical_address"),mc=q.arg("multicast"),p=q.arg("port"),t=q.arg("diag_timeout"),i=q.arg("probe_interval");uint32_t x;if(!parsePa(pa.c_str(),c.paSet,c.pa)||!parseIp(mc.c_str(),c.multicast)||!parseUInt(p.c_str(),1,65535,x)){r.sendText("Adresse physique, multicast ou port invalide",400);return;}c.port=x;if(!parseUInt(t.c_str(),3000,60000,c.timeoutMs)||!parseUInt(i.c_str(),500,10000,c.probeMs)||!valid(c)){r.sendText("Parametres de diagnostic invalides",400);return;}if(!saveConfig(c)){r.sendText("Echec enregistrement NVS",500);return;}config=c;configLoaded=true;r.sendText("Configuration enregistree. Les parametres de routage restent inactifs.");}
void diagnosticPost(WebRequest& q,WebResponse& r,void*){String action=q.hasArg("action")?q.arg("action"):"diagnostic";if(action=="listen_stop"){ipListenEnabled=false;leaveMulticast();r.sendText("Ecoute KNXnet/IP arretee; routage toujours desactive.");return;}if(action=="listen_start"){ipListenEnabled=true;joinMulticast();r.sendText(ipJoined?"Ecoute KNXnet/IP active.":"Ecoute demandee; inscription a la prochaine connexion Wi-Fi.",202);return;}if(action=="display_toggle"){ipDisplayPaused=!ipDisplayPaused;r.sendText(ipDisplayPaused?"Journal fige; la reception et les compteurs continuent.":"Journal repris.");return;}if(action=="clear_log"){ipLogHead=ipLogCount=0;r.sendText("Journal KNXnet/IP efface.");return;}if(action!="diagnostic"){r.sendText("Action inconnue",400);return;}if(diag==Diag::Running||diag==Diag::ResetReceived){r.sendText("Diagnostic deja en cours",409);return;}startDiagnostic();r.sendText("Diagnostic lance; consulter KNX - Etat",202);}

void appSetup(){static_assert(ROUTING_ARMED==0,"Cette version Web conserve le routage verrouille");Serial.begin(SERIAL_BAUD);WiFi.onEvent(wifiEvent);knxSerial.begin(KNX_UART_BAUD,SERIAL_8E1,KNX_RX_PIN,KNX_TX_PIN);configLoaded=loadConfig();if(!configLoaded)setText(lastDiagnostic,sizeof(lastDiagnostic),"Configuration KNX par defaut chargee");bool ok=espBase.addPage("KNX - Etat","/knx",statePage)&&espBase.addPage("KNX - Config","/knx-config",configPage)&&espBase.addPostRoute("/knx-config-save",configPost)&&espBase.addPostRoute("/knx-diagnostic",diagnosticPost);if(!ok)setText(lastError,sizeof(lastError),"Enregistrement routes Web impossible");espBase.begin();Serial.println(F("[SECURITE] ROUTING_ARMED=0; ecoute UDP seule, routage et tunnels arretes"));startDiagnostic();}
void appLoop(){espBase.loop();serviceDiagnostic();serviceIpListener();uint32_t now=millis();if(WiFi.status()==WL_CONNECTED&&elapsed(now,wifiLastSample,1000)){wifiLastSample=now;wifiRssiLast=WiFi.RSSI();if(!wifiRssiMin||wifiRssiLast<wifiRssiMin)wifiRssiMin=wifiRssiLast;}/* knx.start() et knx.loop() volontairement absents. */}
} // namespace

void setup(){appSetup();}
void loop(){appLoop();}
